import { createServer, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import type { Page, Route } from '@playwright/test';

// The E2E build fetches models from `${PUBLIC_MODEL_BASE_URL}` = http://localhost:4399/test-models (see
// playwright.config.ts). Nothing is served there: each test answers those requests itself, with generated bytes of
// the model's real size, so no model files ever go into dist. The bytes stream from a local server (the request is
// re-pointed at it), so a large model's body never has to pass through route.fulfill.

export const MODEL_ROUTE = '**/test-models/**';

/** The page's exact model size in bytes (data-model-bytes, from MODELS in src/ai/config.ts). */
export async function modelBytes(page: Page): Promise<number> {
  return Number(await page.locator('[data-kind="ai"]').getAttribute('data-model-bytes'));
}

export type ModelMode = 'serve' | 'abort' | 'slow' | 'bad';

/**
 * Answer model requests for this page. `mode` can be changed between steps; `requests` counts every request made.
 * 'slow' streams the body in 250 KB pieces every 200 ms, so download progress can be watched.
 * 'bad' serves a body of the right length that the stub tools reject as unparseable.
 */
export async function routeModels(page: Page, bytes: number, opts: { body?: Buffer } = {}) {
  // `body`: the real model file to serve, in place of generated bytes. Change it between steps like `mode`.
  const state = { mode: 'serve' as ModelMode, requests: 0, body: opts.body };
  let server: Server | undefined;
  let serverUrl: Promise<string> | undefined; // one server per page, however many requests race to start it

  await page.route(MODEL_ROUTE, async (route: Route) => {
    state.requests++;
    if (state.mode === 'abort') return route.abort('internetdisconnected');
    if (state.mode !== 'bad' && state.body) return route.fulfill({ status: 200, contentType: 'application/octet-stream', body: state.body });
    serverUrl ??= startServer(bytes, (s) => (server = s));
    // The browser still sees its own URL; the response streams from the local server.
    return route.continue({ url: `${await serverUrl}/${state.mode}` });
  });
  page.once('close', () => server?.close());
  return state;
}

/** Streams `bytes` bytes: /serve as fast as the socket takes them (7s), /bad likewise (zeros), /slow 250 KB per 200 ms. */
function startServer(bytes: number, keep: (s: Server) => void): Promise<string> {
  const PIECE = 2_000_000;
  const pieces = { serve: Buffer.alloc(PIECE, 7), slow: Buffer.alloc(250_000, 7), bad: Buffer.alloc(PIECE, 0) };
  const server = createServer((req, res) => {
    const mode = (req.url?.slice(1) ?? 'serve') as keyof typeof pieces;
    const piece = pieces[mode] ?? pieces.serve;
    res.writeHead(200, {
      'Content-Type': 'application/octet-stream',
      'Content-Length': String(bytes),
      'Access-Control-Allow-Origin': '*',
    });
    let sent = 0;
    let closed = false;
    let timer: ReturnType<typeof setInterval> | undefined;
    req.on('close', () => {
      closed = true;
      clearInterval(timer);
    });
    const next = () => {
      const n = Math.min(piece.length, bytes - sent);
      sent += n;
      const more = res.write(piece.subarray(0, n));
      if (sent >= bytes) {
        clearInterval(timer);
        res.end();
        return false;
      }
      return more;
    };
    if (mode === 'slow') {
      timer = setInterval(next, 200);
      return;
    }
    const pump = () => {
      while (!closed && next());
      if (!closed && sent < bytes) res.once('drain', pump);
    };
    pump();
  });
  keep(server);
  return new Promise((resolve) =>
    server.listen(0, '127.0.0.1', () => resolve(`http://127.0.0.1:${(server.address() as AddressInfo).port}`)),
  );
}
